                          const items = userEventRsvps.grouped?.[group] || [];
                          const label = group === 'going' ? 'Going' : group === 'maybe' ? 'Maybe' : 'Not Going';
                          const color = group === 'going' ? '#28a745' : group === 'maybe' ? '#ffc107' : '#dc3545';
